REVOKE ALL ON public.location_to_terms,public.location_to_sheets,public.location_to_allocations,public.location_to_sheet_entries,public.personnel_agency_provenance FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.location_to_terms,public.location_to_sheets TO authenticated;GRANT SELECT ON public.location_to_allocations,public.location_to_sheet_entries,public.personnel_agency_provenance TO authenticated;GRANT ALL ON public.location_to_terms,public.location_to_sheets,public.location_to_allocations,public.location_to_sheet_entries,public.personnel_agency_provenance TO service_role;
CREATE FUNCTION public.guard_used_to_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid;BEGIN IF TG_TABLE_NAME='location_task_orders' THEN oid:=OLD.id;ELSE oid:=OLD.task_order_id;END IF;IF EXISTS(SELECT 1 FROM location_to_allocations WHERE task_order_id=oid) OR EXISTS(SELECT 1 FROM location_to_sheet_entries e JOIN location_to_sheets s ON s.id=e.sheet_id WHERE s.task_order_id=oid) THEN RAISE EXCEPTION 'Used TO authorization is immutable; create a change order';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.guard_used_to_order() FROM PUBLIC,anon,authenticated;CREATE TRIGGER used_to_order BEFORE UPDATE OR DELETE ON public.location_task_orders FOR EACH ROW EXECUTE FUNCTION public.guard_used_to_order();CREATE TRIGGER used_to_lines BEFORE UPDATE OR DELETE ON public.location_task_order_lines FOR EACH ROW EXECUTE FUNCTION public.guard_used_to_order();
CREATE FUNCTION public.guard_sheet_source_edit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM location_to_sheet_entries WHERE visit_personnel_id=OLD.id AND voided_at IS NULL) THEN IF TG_OP='DELETE' OR NEW.checked_in_at IS DISTINCT FROM OLD.checked_in_at OR NEW.checked_out_at IS DISTINCT FROM OLD.checked_out_at OR NEW.signature_url IS DISTINCT FROM OLD.signature_url THEN RAISE EXCEPTION 'TO sheet evidence is immutable; use a new audited correction';END IF;END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.guard_sheet_source_edit() FROM PUBLIC,anon,authenticated;CREATE TRIGGER to_sheet_source_evidence BEFORE UPDATE OR DELETE ON public.visit_personnel FOR EACH ROW EXECUTE FUNCTION public.guard_sheet_source_edit();
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.complete_to_sheet(uuid,uuid,uuid,text)'::regprocedure) INTO d;d:=replace(d,'PERFORM _guard_punch_recount(p_stay,v.checked_in_at,v.checked_out_at);','IF (v.checked_in_at AT TIME ZONE COALESCE((SELECT timezone FROM project_locations WHERE id=s.location_id),''America/Chicago''))::date<>s.effective_date THEN RAISE EXCEPTION ''Signed stay must be on the TO effective day'';END IF; PERFORM _guard_punch_recount(p_stay,v.checked_in_at,v.checked_out_at);');EXECUTE d;END $$;
COMMENT ON TABLE public.location_to_terms IS 'Private TO billing terms; no financial fields are added to public task-order projections';